"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[3295],{9137(e,n,t){t.r(n),t.d(n,{assets:()=>p,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"part2-backend-platform-security/registering-new-users","title":"First Login and User Provisioning with OIDC and FastAPI","description":"Authentication proves an external identity; provisioning creates the application account, tenant membership, and starting authorization state.","source":"@site/docs/part2-backend-platform-security/08-registering-new-users.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/08-registering-new-users","permalink":"/tutorials/part2-backend-platform-security/08-registering-new-users","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":8,"frontMatter":{"title":"First Login and User Provisioning with OIDC and FastAPI","slug":"/part2-backend-platform-security/08-registering-new-users","description":"Authentication proves an external identity; provisioning creates the application account, tenant membership, and starting authorization state.","sidebar_label":"9. First login and user provisioning","pagination_label":"9. First login and user provisioning","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"8. OIDC, OAuth 2.0, and PKCE in FastAPI","permalink":"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi"},"next":{"title":"10. Authentication deep dive","permalink":"/tutorials/part2-backend-platform-security/09-authentication-deep-dive"}}');var a=t(4848),s=t(8453),o=t(8172);const r=JSON.parse('{"sourcePath":"part2-backend-platform-security/08-registering-new-users.html","route":"/part2-backend-platform-security/08-registering-new-users","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"First Login and User Provisioning","title":"First Login and User Provisioning with OIDC and FastAPI","description":"Authentication proves an external identity; provisioning creates the application account, tenant membership, and starting authorization state.","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-new-user-sign-in-flow-react-google-oidc-fastapi","label":"1. New User Sign-In Flow (React + Google OIDC + FastAPI)"},{"id":"2-example-fastapi-endpoint-for-user-provisioning","label":"2. Example FastAPI Endpoint for User Provisioning"},{"id":"3-where-registration-actually-lives","label":"3. Where \\"Registration\\" Actually Lives"},{"id":"4-choose-a-provisioning-policy-explicitly","label":"4. Choose a Provisioning Policy Explicitly"},{"id":"5-make-first-login-race-safe","label":"5. Make First Login Race-Safe"},{"id":"6-sign-in-is-ongoing-reconciliation","label":"6. Sign-In Is Ongoing Reconciliation"}],"html":"<p class=\\"lead\\">Authentication proves an external identity; provisioning creates the application account, tenant membership, and starting authorization state.</p>\\n\\n    <div class=\\"tr-note\\">\\n        <strong>Where this fits</strong>\\n        The preceding chapters established OIDC Authorization Code with PKCE\\n        and API token validation. This chapter begins after a token has been\\n        validated. It explains just-in-time provisioning without confusing an\\n        identity-provider account, an application user, and a tenant\\n        membership.\\n    </div>\\n\\n    <p class=\\"note\\">Assume the organisation\'s Google Workspace policy already allows this person to authenticate. That permission does not by itself grant access to this application or any tenant data.</p>\\n\\n    <figure class=\\"figure-card\\">\\n        <svg viewBox=\\"0 0 1000 330\\" role=\\"img\\" aria-labelledby=\\"provision-title provision-desc\\">\\n            <title id=\\"provision-title\\">First-login authentication and provisioning state machine</title>\\n            <desc id=\\"provision-desc\\">The browser authenticates with the identity provider, the API validates a token, then an atomic bootstrap either returns an existing user or creates an allowed tenant membership.</desc>\\n            <defs>\\n                <marker id=\\"provision-arrow\\" markerWidth=\\"10\\" markerHeight=\\"10\\" refX=\\"8\\" refY=\\"5\\" orient=\\"auto\\">\\n                    <path d=\\"M0,0 L10,5 L0,10 Z\\" fill=\\"#1769e0\\"></path>\\n                </marker>\\n            </defs>\\n            <rect x=\\"25\\" y=\\"70\\" width=\\"170\\" height=\\"90\\" rx=\\"12\\" fill=\\"#e8f2ff\\" stroke=\\"#1769e0\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"110\\" y=\\"106\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Browser</text>\\n            <text x=\\"110\\" y=\\"134\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">Auth Code + PKCE</text>\\n\\n            <rect x=\\"270\\" y=\\"70\\" width=\\"190\\" height=\\"90\\" rx=\\"12\\" fill=\\"#f1ecff\\" stroke=\\"#7548d8\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"365\\" y=\\"106\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Identity provider</text>\\n            <text x=\\"365\\" y=\\"134\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">authenticate identity</text>\\n\\n            <rect x=\\"535\\" y=\\"70\\" width=\\"190\\" height=\\"90\\" rx=\\"12\\" fill=\\"#fff6df\\" stroke=\\"#bf8700\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"630\\" y=\\"106\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">FastAPI boundary</text>\\n            <text x=\\"630\\" y=\\"134\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">verify iss, aud, exp, sub</text>\\n\\n            <rect x=\\"800\\" y=\\"35\\" width=\\"175\\" height=\\"90\\" rx=\\"12\\" fill=\\"#e9fbf2\\" stroke=\\"#14875a\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"887\\" y=\\"71\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">Existing user</text>\\n            <text x=\\"887\\" y=\\"99\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">refresh last login</text>\\n\\n            <rect x=\\"800\\" y=\\"195\\" width=\\"175\\" height=\\"100\\" rx=\\"12\\" fill=\\"#fcebea\\" stroke=\\"#cf222e\\" stroke-width=\\"2\\"></rect>\\n            <text x=\\"887\\" y=\\"229\\" text-anchor=\\"middle\\" font-size=\\"17\\" font-weight=\\"700\\" fill=\\"#162033\\">New identity</text>\\n            <text x=\\"887\\" y=\\"256\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">policy + atomic upsert</text>\\n            <text x=\\"887\\" y=\\"278\\" text-anchor=\\"middle\\" font-size=\\"14\\" fill=\\"#4f6078\\">or deny</text>\\n\\n            <line x1=\\"195\\" y1=\\"115\\" x2=\\"270\\" y2=\\"115\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#provision-arrow)\\"></line>\\n            <line x1=\\"460\\" y1=\\"115\\" x2=\\"535\\" y2=\\"115\\" stroke=\\"#1769e0\\" stroke-width=\\"3\\" marker-end=\\"url(#provision-arrow)\\"></line>\\n            <path d=\\"M725 105 C755 90 765 80 800 80\\" fill=\\"none\\" stroke=\\"#14875a\\" stroke-width=\\"3\\" marker-end=\\"url(#provision-arrow)\\"></path>\\n            <path d=\\"M725 130 C760 155 770 225 800 240\\" fill=\\"none\\" stroke=\\"#cf222e\\" stroke-width=\\"3\\" marker-end=\\"url(#provision-arrow)\\"></path>\\n            <text x=\\"752\\" y=\\"76\\" font-size=\\"13\\" fill=\\"#14875a\\">found</text>\\n            <text x=\\"748\\" y=\\"201\\" font-size=\\"13\\" fill=\\"#cf222e\\">not found</text>\\n        </svg>\\n        <figcaption>\\n            Identity verification precedes provisioning. The create-or-return\\n            step must be atomic because two browser requests can arrive for\\n            the same first login.\\n        </figcaption>\\n    </figure>\\n\\n    <hr>\\n\\n    <h2 id=\\"1-new-user-sign-in-flow-react-google-oidc-fastapi\\">1. New User Sign-In Flow (React + Google OIDC + FastAPI)</h2>\\n\\n    <div class=\\"highlight-box\\">\\n        <strong>Key idea:</strong> The login page doesn\'t \\"register\\" the user with Google\u2014Google already knows them. Your app \\"registers\\" the user by provisioning a record in your database the first time your backend sees a valid identity.\\n    </div>\\n    \\n    <ol>\\n        <li><strong>User clicks \\"Sign in with Google\\"</strong>\\n            <p>React starts OIDC Authorization Code + PKCE by redirecting the browser to Google\'s authorization endpoint.</p>\\n            <p><em>Outcome: user authenticates with Google (SSO).</em></p>\\n        </li>\\n        <li><strong>The registered client completes the code exchange</strong>\\n            <p>In a browser-only public-client design, React can exchange the authorization code using its PKCE verifier and keep tokens in memory. In a backend-for-frontend design, the backend completes the exchange and gives the browser an HTTP-only session cookie.</p>\\n            <p>The credential sent to your API must be an <strong>access token issued for that API\'s audience</strong>. An OIDC ID token describes the login result for its client; it is not a general-purpose API bearer token. A Google-only application may instead validate the login at its backend and mint an application session.</p>\\n        </li>\\n        <li><strong>React calls a bootstrap endpoint on your API</strong>\\n            <p>Right after login, the frontend calls something like:</p>\\n            <ul>\\n                <li><code>POST /auth/bootstrap</code> for an operation that may create or update application records, then</li>\\n                <li><code>GET /me</code> for later read-only profile retrieval.</li>\\n            </ul>\\n            <p>with:</p>\\n            <pre><code>Authorization: Bearer &lt;access_token&gt;</code></pre>\\n            <p><em>Purpose: let the backend validate the token and decide what to do with this identity.</em></p>\\n        </li>\\n        <li><strong>FastAPI validates token and extracts stable identity</strong>\\n            <p>Backend verifies the token (signature + issuer/audience/expiry), then reads claims like:</p>\\n            <ul>\\n                <li><code>sub</code> \u2192 stable user identifier at this IdP</li>\\n                <li><code>email</code> and <code>email_verified</code> \u2192 optional policy inputs, never the stable primary key</li>\\n            </ul>\\n        </li>\\n        <li><strong>Backend checks if the user already exists in your DB</strong>\\n            <p>Backend looks up by a stable key like <code>(issuer, sub)</code> (best practice), optionally storing email too.</p>\\n            <p><strong>Case A: user exists</strong></p>\\n            <ul>\\n                <li>Return user profile + tenant info.</li>\\n                <li>Frontend proceeds normally.</li>\\n            </ul>\\n            <p><strong>Case B: user is new</strong></p>\\n            <ul>\\n                <li>This is where \\"registration\\" happens (provisioning).</li>\\n            </ul>\\n        </li>\\n    </ol>\\n\\n    <hr>\\n\\n    <h2 id=\\"2-example-fastapi-endpoint-for-user-provisioning\\">2. Example FastAPI Endpoint for User Provisioning</h2>\\n    <p>This endpoint is the bootstrap call that validates the Bearer token, looks up the user, creates the DB row if missing, and returns user details.</p>\\n    <p class=\\"callout warn\\">The code below is a teaching scaffold. The industry-standard version verifies the token against JWKS/OIDC discovery, stores users in a real database with a unique constraint on <code>(issuer, subject)</code>, performs the create-or-return logic in a transaction/upsert, and records audit fields such as <code>created_at</code> and <code>last_login_at</code>.</p>\\n    <pre><code class=\\"language-python\\"><span style=\\"color: #0000ff;\\">from</span> fastapi <span style=\\"color: #0000ff;\\">import</span> FastAPI, Depends, HTTPException\\n<span style=\\"color: #0000ff;\\">from</span> fastapi.security <span style=\\"color: #0000ff;\\">import</span> HTTPAuthorizationCredentials, HTTPBearer\\n<span style=\\"color: #0000ff;\\">from</span> pydantic <span style=\\"color: #0000ff;\\">import</span> BaseModel\\n<span style=\\"color: #0000ff;\\">from</span> datetime <span style=\\"color: #0000ff;\\">import</span> datetime, timezone\\n\\napp = FastAPI()\\nbearer = HTTPBearer(auto_error=<span style=\\"color: #0000ff;\\">True</span>)\\n\\n<span style=\\"color: #0000ff;\\">class</span> <span style=\\"color: #2b91af;\\">BootstrapResponse</span>(BaseModel):\\n    user_id: str\\n    tenant_id: str\\n    is_new_user: bool\\n\\n\\t<span style=\\"color: #008000;\\"># --- Teaching-only in-memory store (production: Postgres/Cloud SQL) ---</span>\\nUSERS_BY_ISS_SUB: dict[tuple[str, str], dict] = {}  <span style=\\"color: #008000;\\"># key = (issuer, sub)</span>\\n\\n\\t<span style=\\"color: #008000;\\"># --- Teaching-only token verifier (production: JWT/JWKS validation) ---</span>\\n<span style=\\"color: #0000ff;\\">def</span> <span style=\\"color: #795e26;\\">verify_and_decode_access_token</span>(token: str) -&gt; dict:\\n    <span style=\\"color: #a31515;\\">\\"\\"\\"\\n\\t    Production implementation:\\n\\t      - verify JWT signature using Google JWKS\\n\\t      - check issuer (iss), audience (aud), expiry (exp)\\n\\t      - optionally check nonce/azp/scopes depending on token type\\n\\t    This teaching version returns mock claims so you see where they come from.\\n    \\"\\"\\"</span>\\n    <span style=\\"color: #008000;\\"># demo-alice-token is only a classroom stand-in for an already-verified JWT.</span>\\n    <span style=\\"color: #0000ff;\\">if</span> token == <span style=\\"color: #a31515;\\">\\"demo-alice-token\\"</span>:\\n        <span style=\\"color: #0000ff;\\">return</span> {\\n            <span style=\\"color: #a31515;\\">\\"iss\\"</span>: <span style=\\"color: #a31515;\\">\\"https://accounts.google.com\\"</span>,\\n            <span style=\\"color: #a31515;\\">\\"sub\\"</span>: <span style=\\"color: #a31515;\\">\\"user-A-sub\\"</span>,\\n            <span style=\\"color: #a31515;\\">\\"email\\"</span>: <span style=\\"color: #a31515;\\">\\"alice@acme.com\\"</span>,\\n            <span style=\\"color: #a31515;\\">\\"email_verified\\"</span>: <span style=\\"color: #0000ff;\\">True</span>,\\n        }\\n    <span style=\\"color: #0000ff;\\">raise</span> HTTPException(status_code=<span style=\\"color: #098658;\\">401</span>, detail=<span style=\\"color: #a31515;\\">\\"Invalid/expired token\\"</span>)\\n\\n<span style=\\"color: #0000ff;\\">def</span> <span style=\\"color: #795e26;\\">map_email_to_tenant_id</span>(email: str) -&gt; str:\\n    <span style=\\"color: #a31515;\\">\\"\\"\\"\\n    Example tenant mapping policy: email domain -&gt; tenant.\\n    (Alternative policies: invite-only lookup, explicit claim, etc.)\\n    \\"\\"\\"</span>\\n    domain = email.split(<span style=\\"color: #a31515;\\">\\"@\\"</span>)[<span style=\\"color: #098658;\\">-1</span>].lower()\\n    <span style=\\"color: #0000ff;\\">if</span> domain == <span style=\\"color: #a31515;\\">\\"acme.com\\"</span>:\\n        <span style=\\"color: #0000ff;\\">return</span> <span style=\\"color: #a31515;\\">\\"tenant-acme\\"</span>\\n    <span style=\\"color: #0000ff;\\">raise</span> HTTPException(status_code=<span style=\\"color: #098658;\\">403</span>, detail=<span style=\\"color: #a31515;\\">\\"No tenant mapping for this user\\"</span>)\\n\\n@app.post(<span style=\\"color: #a31515;\\">\\"/auth/bootstrap\\"</span>, response_model=BootstrapResponse)\\n<span style=\\"color: #0000ff;\\">def</span> <span style=\\"color: #795e26;\\">auth_bootstrap</span>(creds: HTTPAuthorizationCredentials = Depends(bearer)):\\n    <span style=\\"color: #008000;\\"># 1) Extract raw token from \\"Authorization: Bearer &lt;token&gt;\\"</span>\\n    token = creds.credentials\\n\\n    <span style=\\"color: #008000;\\"># 2) Validate + decode -&gt; claims (iss/sub/email)</span>\\n    claims = verify_and_decode_access_token(token)\\n    issuer = claims[<span style=\\"color: #a31515;\\">\\"iss\\"</span>]\\n    sub = claims[<span style=\\"color: #a31515;\\">\\"sub\\"</span>]\\n    email = claims.get(<span style=\\"color: #a31515;\\">\\"email\\"</span>, <span style=\\"color: #a31515;\\">\\"\\"</span>)\\n    <span style=\\"color: #0000ff;\\">if not</span> claims.get(<span style=\\"color: #a31515;\\">\\"email_verified\\"</span>, <span style=\\"color: #0000ff;\\">False</span>):\\n        <span style=\\"color: #0000ff;\\">raise</span> HTTPException(status_code=<span style=\\"color: #098658;\\">403</span>, detail=<span style=\\"color: #a31515;\\">\\"Verified email required\\"</span>)\\n\\n    <span style=\\"color: #008000;\\"># 3) Look up user by stable key (issuer, sub)</span>\\n    key = (issuer, sub)\\n    existing = USERS_BY_ISS_SUB.get(key)\\n\\n    <span style=\\"color: #0000ff;\\">if</span> existing:\\n        <span style=\\"color: #008000;\\"># User already provisioned</span>\\n        <span style=\\"color: #0000ff;\\">return</span> BootstrapResponse(\\n            user_id=existing[<span style=\\"color: #a31515;\\">\\"user_id\\"</span>],\\n            tenant_id=existing[<span style=\\"color: #a31515;\\">\\"tenant_id\\"</span>],\\n            is_new_user=<span style=\\"color: #0000ff;\\">False</span>,\\n        )\\n\\n    <span style=\\"color: #008000;\\"># 4) New user -&gt; determine tenant_id (domain/invite/etc.)</span>\\n    tenant_id = map_email_to_tenant_id(email)\\n\\n    <span style=\\"color: #008000;\\"># 5) \\"Register\\" user in DB (provision)</span>\\n    user_row = {\\n        <span style=\\"color: #a31515;\\">\\"user_id\\"</span>: <span style=\\"color: #a31515;\\">f\\"db-user-<span style=\\"color: #000;\\">{sub}</span>\\"</span>,  <span style=\\"color: #008000;\\"># in real DB: UUID</span>\\n        <span style=\\"color: #a31515;\\">\\"tenant_id\\"</span>: tenant_id,\\n        <span style=\\"color: #a31515;\\">\\"issuer\\"</span>: issuer,\\n        <span style=\\"color: #a31515;\\">\\"sub\\"</span>: sub,\\n        <span style=\\"color: #a31515;\\">\\"email\\"</span>: email,\\n        <span style=\\"color: #a31515;\\">\\"created_at\\"</span>: datetime.now(timezone.utc).isoformat(),\\n    }\\n    USERS_BY_ISS_SUB[key] = user_row\\n\\n    <span style=\\"color: #0000ff;\\">return</span> BootstrapResponse(\\n        user_id=user_row[<span style=\\"color: #a31515;\\">\\"user_id\\"</span>],\\n        tenant_id=user_row[<span style=\\"color: #a31515;\\">\\"tenant_id\\"</span>],\\n        is_new_user=<span style=\\"color: #0000ff;\\">True</span>,\\n    )</code></pre>\\n\\n    <hr>\\n\\n    <ol start=\\"6\\">\\n        <li><strong>Provision the user (your app\'s \\"registration\\")</strong>\\n            <p>The backend creates the required records:</p>\\n            <ol>\\n                <li><strong>Determine tenant_id</strong>\\n                    <ul>\\n                        <li>Domain mapping: <code>alice@acme.com</code> \u2192 tenant \\"acme\\"</li>\\n                        <li>or invite-only: user must already be linked to a tenant</li>\\n                        <li>or self-serve tenant creation (first user creates tenant)</li>\\n                    </ul>\\n                </li>\\n                <li><strong>Create user row</strong>\\n                    <ul>\\n                        <li>Store: <code>issuer</code>, <code>sub</code>, <code>email</code>, <code>tenant_id</code>, timestamps</li>\\n                    </ul>\\n                </li>\\n                <li><strong>Optional defaults</strong>\\n                    <ul>\\n                        <li>Preferences, empty workspace, default roles, etc.</li>\\n                    </ul>\\n                </li>\\n            </ol>\\n        </li>\\n        <li><strong>Backend returns a bootstrap response</strong>\\n            <p>Example:</p>\\n            <pre><code>{\\n  <span style=\\"color: #a31515;\\">\\"user_id\\"</span>: <span style=\\"color: #a31515;\\">\\"\u2026\\"</span>,\\n  <span style=\\"color: #a31515;\\">\\"tenant_id\\"</span>: <span style=\\"color: #a31515;\\">\\"\u2026\\"</span>,\\n  <span style=\\"color: #a31515;\\">\\"is_new_user\\"</span>: <span style=\\"color: #0000ff;\\">true</span>\\n}</code></pre>\\n            <p>React can now show an onboarding / \\"upload documents\\" screen.</p>\\n        </li>\\n    </ol>\\n\\n    <hr>\\n\\n    <h2 id=\\"3-where-registration-actually-lives\\">3. Where \\"Registration\\" Actually Lives</h2>\\n    <ul>\\n        <li>Google authenticates the user.</li>\\n        <li>Your backend decides whether the identity is allowed and attaches it to a tenant.</li>\\n        <li><strong>\\"Registration\\" = your DB provisioning, not creating credentials.</strong></li>\\n    </ul>\\n\\n    <h2 id=\\"4-choose-a-provisioning-policy-explicitly\\">4. Choose a Provisioning Policy Explicitly</h2>\\n    <table>\\n        <thead>\\n            <tr><th>Policy</th><th>How a new identity becomes a user</th><th>Use when</th></tr>\\n        </thead>\\n        <tbody>\\n            <tr><td>Invite only</td><td>A pending invitation already binds an email or subject to a tenant and initial role.</td><td>Controlled B2B and regulated applications.</td></tr>\\n            <tr><td>Just in time (JIT)</td><td>A verified identity that satisfies policy is created during first login.</td><td>Managed workforce domains with clear admission rules.</td></tr>\\n            <tr><td>SCIM / directory sync</td><td>An identity-management system creates, updates, and disables users before login.</td><td>Enterprise lifecycle automation and rapid deprovisioning.</td></tr>\\n            <tr><td>Self-service tenant creation</td><td>The first allowed user creates a tenant and becomes its initial administrator.</td><td>SaaS onboarding with abuse controls and verification.</td></tr>\\n        </tbody>\\n    </table>\\n\\n    <p>\\n        Domain mapping such as <code>@acme.com \u2192 tenant-acme</code> is a\\n        teaching example, not a universal policy. Use it only with a verified\\n        email, an owned-domain registry, and an explicit business rule.\\n        Invitations or directory-managed membership are safer when the same\\n        domain can contain people who must not share application data.\\n    </p>\\n\\n    <h2 id=\\"5-make-first-login-race-safe\\">5. Make First Login Race-Safe</h2>\\n    <p>\\n        Browsers retry, users double-click, and multiple tabs can call\\n        bootstrap simultaneously. An in-memory check followed by an insert is\\n        not sufficient in production. Put a unique constraint on\\n        <code>(issuer, subject)</code> and perform an upsert or transaction:\\n    </p>\\n\\n    <pre><code class=\\"language-sql\\">INSERT INTO app_user (issuer, subject, email, status, created_at)\\nVALUES (:issuer, :subject, :email, \'active\', CURRENT_TIMESTAMP)\\nON CONFLICT (issuer, subject)\\nDO UPDATE SET\\n    email = EXCLUDED.email,\\n    last_login_at = CURRENT_TIMESTAMP\\nRETURNING user_id, status;</code></pre>\\n\\n    <p>\\n        Tenant membership should have its own unique key, such as\\n        <code>(tenant_id, user_id)</code>. Keeping identity and membership\\n        separate supports users who legitimately belong to more than one\\n        tenant and avoids treating tenant data as an attribute permanently\\n        embedded in the identity-provider account.\\n    </p>\\n\\n    <h2 id=\\"6-sign-in-is-ongoing-reconciliation\\">6. Sign-In Is Ongoing Reconciliation</h2>\\n    <p>\\n        The second login is not simply \\"do nothing.\\" Update safe profile\\n        metadata such as display name, verified email, and\\n        <code>last_login_at</code>; evaluate whether the application user or\\n        membership is suspended; and apply current authorization policy.\\n        Never silently reactivate a locally disabled user merely because the\\n        identity provider authenticated them.\\n    </p>\\n    <ul>\\n        <li>Use <code>(iss, sub)</code> as the external identity key; email addresses can change or be reassigned.</li>\\n        <li>Model user status and membership status separately: invited, active, suspended, or removed.</li>\\n        <li>Decide whether group and role changes are read on every login, synchronized by SCIM, or maintained locally.</li>\\n        <li>Record provisioning, membership changes, denial reasons, and the policy version in an audit trail.</li>\\n        <li>Define deprovisioning and session revocation; login is only one part of the account lifecycle.</li>\\n    </ul>\\n\\n    <div class=\\"tr-tip\\">\\n        <strong>Correct mental model</strong>\\n        The identity provider owns credentials and authentication. Your\\n        application owns admission, the internal user record, tenant\\n        memberships, roles, and data authorization.\\n    </div>"}'),l={title:"First Login and User Provisioning with OIDC and FastAPI",slug:"/part2-backend-platform-security/08-registering-new-users",description:"Authentication proves an external identity; provisioning creates the application account, tenant membership, and starting authorization state.",sidebar_label:"9. First login and user provisioning",pagination_label:"9. First login and user provisioning",hide_title:!0,hide_table_of_contents:!0},c=void 0,p={},d=[];function u(e){return(0,a.jsx)(o.A,{content:r})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(u,{...e})}):u()}}}]);